            let page = self.conversations_page(after.as_ref(), PageBudget::default())?;
            result.extend(page.items.into_iter().map(|m| m.conversation));
            after = page.next;
            if after.is_none() {
                return Ok(result);
            }
        }
    }
    pub(super) fn order_appended(
        &self,
        c: &Connection,
        e: &Event,
        revision: i64,
        count: i64,
    ) -> Result<(), LogError> {
        self.require_active_on(c, &e.conversation_id)?;
        for kind in [CausalOrder::Logical, CausalOrder::WallClock] {
            let Some(job) = self.order_job(c, &e.conversation_id, kind)? else {
