                    return Err(corrupt("ready order lacks current generation"));
                }
            }
            c.execute(
                "UPDATE event_order_jobs SET source_revision=?2,target_count=?3 WHERE job=?1",
                params![job.id.as_slice(), revision, count],
            )?;
        }
        Ok(())
    }
